package org.brightstats.model;
import java.util.*;
import java.nio.file.*;
import com.google.gson.*;
import org.brightstats.model.ElementType.Family;
import org.brightstats.model.TypedDiagram.*;
public final class TypedDiagramChecks {
    static int checks;static void check(boolean condition){checks++;if(!condition)throw new AssertionError("Typed diagram check "+checks);}
    static void reject(Runnable action){try{action.run();throw new AssertionError("Invalid diagram accepted");}catch(IllegalArgumentException expected){checks++;}}
    static Node node(String id,ElementType type,String label,double x,double y){return new Node(id,type,label,x,y,new JsonObject());}
    static Node anchor(String id,String edge){JsonObject properties=new JsonObject();properties.addProperty("edge",edge);return new Node(id,ElementType.DONGLE,"",0,0,properties);}
    static Link link(String id,ElementType type,String source,String target){return new Link(id,type,source,target,new JsonObject());}
    public static void main(String[] args)throws Exception{
        check(ElementType.values().length==51);for(Family family:Family.values()){var empty=TypedDiagram.empty(family);check(empty.nodes().size()==1);check(TypedDiagram.parse(empty.json().toString()).equals(empty));}
        var base=new Document(1,Family.PLS,"root",List.of(node("root",ElementType.ROOT,"Model",0,0),node("x",ElementType.LATENT_VARIABLE,"X",100,100),node("y",ElementType.LATENT_VARIABLE,"Y",500,100),node("w",ElementType.LATENT_VARIABLE,"W",250,300)),List.of(link("xy",ElementType.CONNECTION_BETWEEN_LV_AND_LV,"x","y")),List.of());
        base=base.with(anchor("anchor","xy")).with(link("moderation",ElementType.CONNECTION_FOR_PLS_MODERATION,"w","anchor")).with(anchor("nested","moderation"));base=base.with(new Annotation("path_label",ElementType.CONNECTION_LABEL,"xy","A path <&> beta",300,60,180,40)).with(new Annotation("external_label",ElementType.NODE_EXTERNAL_LABEL,"x","Explanatory construct",20,20,200,40)).with(new Annotation("note",ElementType.POSTIT,"","Notes with Unicode alpha: α",30,350,220,90));
        check(base.nodes().size()==6&&base.links().size()==2&&base.annotations().size()==3);check(base.node("x").label().equals("X"));check(base.with(base.node("x").named("Renamed X")).link("xy").source().equals("x"));check(base.move(Set.of("x","w","note"),20,-10).node("x").x()==120);check(base.node("x").x()==100);check(base.move(Set.of("x"),0,0).equals(base));
        JsonObject options=new JsonObject();options.addProperty("mode","A");Node immutable=new Node("immutable",ElementType.LATENT_VARIABLE,"Immutable",0,0,options);options.addProperty("mode","B");check(immutable.properties().get("mode").getAsString().equals("A"));var accessor=immutable.properties();accessor.addProperty("mode","B");check(immutable.properties().get("mode").getAsString().equals("A"));
        var removed=base.remove(Set.of("xy"));check(removed.links().isEmpty());check(removed.nodes().size()==4);check(removed.annotations().stream().noneMatch(note->note.id().equals("path_label")));check(removed.annotations().size()==2);check(base.remove(Set.of("x")).nodes().stream().noneMatch(node->node.id().equals("anchor")||node.id().equals("nested")));var rootProtected=base;reject(()->rootProtected.remove(Set.of("root")));
        var fragment=base.fragment(Set.of("x","y","w","note"));var pasted=base.paste(fragment,30,20);check(pasted.document().nodes().size()==11);check(pasted.document().links().size()==4);check(pasted.inserted().size()==10);check(pasted.document().nodes().stream().anyMatch(node->node.label().equals("X copy")));for(var copied:pasted.document().nodes())if(pasted.inserted().contains(copied.id())&&copied.type()==ElementType.DONGLE)check(pasted.inserted().contains(copied.properties().get("edge").getAsString()));check(TypedDiagram.parse(pasted.document().json().toString()).equals(pasted.document()));
        var partial=base.fragment(Set.of("w","anchor","nested"));var partialPaste=base.paste(partial,10,10);check(partialPaste.document().nodes().size()==7);check(partialPaste.document().links().size()==2);
        var finalBase=base;reject(()->finalBase.with(link("bad",ElementType.CONNECTION_BETWEEN_LV_AND_LV,"x","missing")));reject(()->finalBase.with(node("x",ElementType.CBSEM_LATENT_VARIABLE,"Wrong family",0,0)));reject(()->finalBase.with(new Annotation("bad_note",ElementType.CONNECTION_LABEL,"x","Wrong attachment",0,0,100,30)));reject(()->finalBase.with(anchor("missing_anchor","missing")));reject(()->finalBase.with(link("cycle",ElementType.CONNECTION_FOR_PLS_MODERATION,"w","nested")).with(anchor("nested","cycle")));reject(()->node("nan",ElementType.LATENT_VARIABLE,"NaN",Double.NaN,0));reject(()->new Link("self",ElementType.CONNECTION_BETWEEN_LV_AND_LV,"x","x",new JsonObject()));JsonObject nonfinite=new JsonObject();nonfinite.addProperty("value",Double.NaN);reject(()->new Node("bad_number",ElementType.LATENT_VARIABLE,"Bad",0,0,nonfinite));reject(()->TypedDiagram.parse("[".repeat(60)+"]".repeat(60)));reject(()->finalBase.paste(TypedDiagram.empty(Family.CBSEM).fragment(Set.of()),0,0));
        Path output=Path.of(args[0]);Files.createDirectories(output);Files.writeString(output.resolve("identity-diagram.json"),new GsonBuilder().setPrettyPrinting().create().toJson(base));Files.writeString(output.resolve("identity-pasted.json"),new GsonBuilder().setPrettyPrinting().create().toJson(pasted.document()));System.out.println("{\"checks\":"+checks+",\"mapped_types\":"+ElementType.values().length+"}");
    }
}
